		["FourUniqueBootsStrDex2"] = {[1]="«Сирриус летел на крыльях света: быстрее ветра,",[2]="быстрее мысли. Но зря он пытался обогнать тьму:",[3]="она была рядом, ждала его за каждым поворотом».",[4]="- Из сказаний азмири"},
		["FourUniqueBootsStrDex3"] = {[1]="Буре не поколебать тех, кто шагает твёрдо."},
		["FourUniqueBootsStrDex4"] = {[1]="«‎Капитан Хифф Серобородый проделал то, что почти никому",[2]="в Морской гнили не удавалось: он умер от старости.",[3]="Я сам его с десяток раз едва не достал, если б не эта",[4]="его чёртова нога... изворотливый засранец...»"},
		["FourUniqueBootsStrInt2"] = {[1]="Вы! Завидев небес круговерть,",[2]="убегайте: явилась смерть!"},
		["FourUniqueBootsStrInt9"] = {[1]="«Пари. Будь быстр. Никому не позволяй ступать сюда,",[2]="хоть поверху, хоть понизу, не то лишишься своей цели»."},
		["FourUniqueBow1"] = {[1]="«Я выпустила град стрел в сердце человека,",[2]="убившего моего любимого. Не было ни удовлетворения,",[3]="ни облегчения, ни возмездия. Была только... пустота»."},
		["FourUniqueBow13_"] = {[1]="«Братоубийца, ты попираешь свои же обычаи, оборачивая ход битвы!",[2]="Посмотрим же, что сильнее... варварство каруи или мощь Империи!»",[3]="– Генерал Марк Львиный Глаз"},
		["FourUniqueBow14"] = {[1]="Когда Маджи приближались к краю небытия, она нанизывала",[2]="на нить фрагменты каркаса Диколесья. Когда она",[3]="натягивала стрелу, то тянула за собой стихии самой жизни."},
		["FourUniqueBow2"] = {[1]="«Дождь из тысячи оперённых капель",[2]="превращает быль в былое, а жизнь в смерть».",[3]="- Ригвальд из народа эзомитов"},
		["FourUniqueBow3"] = {[1]="Каждый герб был словом тана, прикреплённым к луку Айвора.",[2]="Они либо присоединятся к графу, либо умрут от его рук."},
		["FourUniqueBow4"] = {[1]="Леса Вастири таили много таинственных и тёмных",[2]="секретов. Мужчины приучились туда не ходить,",[3]="чтобы не вернуться со странной новой целью."},
		["FourUniqueBow5"] = {[1]="«Обгорелые, замёрзшие,",[2]="поражённые молнией —",[3]="мне всё едино, а смерти",[4]="и подавно».",[5]="- Коралий «Стрела рока»"},
		["FourUniqueBow6"] = {[1]="Погребальная песня струн",[2]="отдаётся в изгибе арфы,",[3]="что поёт, отпустив стрелу",[4]="отбирать жизнь у новых павших."},
		["FourUniqueBow7"] = {[1]="Зловещий ливень обрушился на нас и увил нитями молний.",[2]="Его волшебная сила чернила металл и уязвляла плоть.",[3]="Ни спасения нам не было, ни укрытия. Воздух полнился отчаянием."},
		["FourUniqueBow8"] = {[1]="Сотня слепых голов, каждая ловит в воздухе вкус добычи."},
		["FourUniqueBow9"] = {[1]="Сила Всепламени разрывает души",[2]="столь же легко, как плоть."},
		["FourUniqueBreach1_"] = {[1]="Мы счастливы отдавать свои члены.",[2]="Сеть сплетена, дабы сберечь кости Повелителей."},
		["FourUniqueBreach2"] = {[1]="Она мыслит – мы действуем.",[2]="Она действует – мы мыслим.",[3]="Части целого, что очищает небеса."},
		["FourUniqueBreach3"] = {[1]="Границы познания защищают",[2]="нас от самих себя."},
		["FourUniqueBreach4a"] = {[1]="Мы – кровь его.",[2]="Через нас он несёт своё пылающее послание."},
		["FourUniqueBreach4b"] = {[1]="Глупец не поклонился.",[2]="Глупец стоял и вопрошал.",[3]="Глупец был вычеркнут."},
		["FourUniqueBreach4c"] = {[1]="Бесконечное падение начинается с единственного мгновения,",[2]="после которого все обречены."},
		["FourUniqueCharm1"] = {[1]="«Даже перед лицом Всемирной зимы жизнь",[2]="нашла лазейку. Дух всегда помогает»."},
		["FourUniqueCharm10"] = {[1]="Море бушует, небо рокочет; два судна кренятся друг к другу.",[2]="Во вспышках света видны только свистящие топоры... и ухмылка."},
		["FourUniqueCharm11"] = {[1]="Среди жрецов, несколько избранных тайно поедали грехи других.",[2]="Они несли эту ношу, чтобы придать сил своему скрытому Ордену."},
		["FourUniqueCharm2"] = {[1]="Рэкласт знавал слишком мало истинных героев.",[2]="Он помнит тех, кто проявил непокорность."},
		["FourUniqueCharm3"] = {[1]="Служителям Богини похоти",[2]="не было нужды бояться её жала."},
		["FourUniqueCharm4"] = {[1]="Они нашли плачущее дитя, привязанное к замёрзшему погребальному костру.",[2]="Она была скована льдом, но деревня была пеплом."},
		["FourUniqueCharm5"] = {[1]="Главный любимец каждого экипажа Морской гнили –",[2]="тот, что отказывается делать любую работу."},
		["FourUniqueCharm6"] = {[1]="«Может, прошли века, но я по-прежнему твёрдо верю.",[2]="Спаситель придёт, и человечество будет свободно»."},
		["FourUniqueCharm7"] = {[1]="«При свисте топора палача твои последние",[2]="мгновения растягиваются в вечность».",[3]="- Ворм, дважды помилованный"},
		["FourUniqueCharm8"] = {[1]="Терпеливостью Каом не отличался."},
		["FourUniqueCharm9"] = {[1]="«Взмыть в небеса,",[2]="коснуться самых облаков –",[3]="вот истинная свобода».",[4]="- Поговорка Немого ветра"},
		["FourUniqueCorruption1"] = {[1]="«Гхорру ведом только голод, только ненасытный пир.",[2]="Он пожрёт всё живое, а потом остальное!».",[3]="- Бредни узника жрецов, страница четырнадцать"},
		["FourUniqueCorruption2"] = {[1]="«Беидату нужен лишь плацдарм, он хочет ухватить твою плоть,",[2]="твой мир... он предложит тебе всё, только бы это получить...»",[3]="- Бредни узника жрецов, страница тридцать"},
		["FourUniqueCorruption3"] = {[1]="«Разум в центре роя... К'Таш думает за всех...",[2]="но мысль у него только одна... ненависть».",[3]="- Бредни узника жрецов, страница девяносто четыре"},
		["FourUniqueCrossbow1"] = {[1]="Шипящие обещания лились путникам в уши.",[2]="В ответ он просил одного: верности..."},
		["FourUniqueCrossbow13"] = {[1]="«И здесь мы останемся...",[2]="заключённые в нашей симфонии вечных мучений.",[3]="Исполнительница и композитор, чьи судьбы вовек переплелись».",[4]="- Адамантия Бректов, композитор"},
		["FourUniqueCrossbow14"] = {[1]="«Время дипломатии прошло!",[2]="Раз они не уважают Дом Азади,",[3]="то пусть умрут славно... и громко.",[4]="Мы – мастера в торговле смертью!»",[5]="- Рата Азади"},
		["FourUniqueCrossbow2"] = {[1]="«У ворот его встретили ревущие трубы",[2]="и развевающиеся знамёна. Такого он не ждал».",[3]="- анонимный отчёт Безмолвного братства"},
		["FourUniqueCrossbow5"] = {[1]="Для тех, кому в Вастири негде укрыться,",[2]="раскалённый день суров, но холодная ночь гораздо хуже."},
		["FourUniqueDelirium1"] = {[1]="Минута затишья перед битвой может решить войну."},
		["FourUniqueDelirium2"] = {[1]="Бог-плут обратил сами День и Ночь друг против друга.",[2]="На что надеешься ты?"},
		["FourUniqueDelirium3"] = {[1]="Что есть жизнь? Лишь спираль полуосознанной паники."},
		["FourUniqueDelirium4"] = {[1]="Грани сдвигаются, мир теряет целостность, бесконечность заполняет всё сущее."},
		["FourUniqueDelirium5"] = {[1]="Эта внутренняя борьба беспросветна,",[2]="но мрак постепенно становится родным."},
		["FourUniqueExpedition1"] = {[1]="Великий щит обнаружили жрецы в ту ночь, когда он упал на Мидденгард,",[2]="но его тайны довелось разгадывать уже кузнецам."},
		["FourUniqueExpedition2"] = {[1]="Веру калгууранских жрецов поддерживали точные расчёты,",[2]="а не беспочвенные обещания."},
		["FourUniqueExpedition3_"] = {[1]="Олрот Храбрый",[2]="устали не знает,",[3]="за тебя и меня",[4]="он кровь проливает!"},
		["FourUniqueExpedition4"] = {[1]="«Сила истинных героев растёт перед лицом испытаний».",[2]="– четвёртая заповедь Рыцарей Солнца"},
		["FourUniqueFocus1"] = {[1]="Плач смерти шепчет на ветру."},
		["FourUniqueFocus2"] = {[1]="Локон золотых волос в дар.",[2]="Война стёрлась из памяти,",[3]="но причины не забыты."},
		["FourUniqueFocus3"] = {[1]="Страшилки, что мы воображали детьми,",[2]="так и живут где-то в темноте..."},
		["FourUniqueFocus4"] = {[1]="Покорность простирается и за могилу."},
		["FourUniqueFocus5"] = {[1]="Извилистый, переплетённый... запутанный."},
		["FourUniqueFocus6"] = {[1]="Вспышка лазури, туча целует чело.",[2]="Танец недвижный в сердце посеет тепло."},
		["FourUniqueFocus7"] = {[1]="Отдай ему своё тело, а следом и бремя."},
		["FourUniqueFocus8"] = {[1]="Ваал избавляли рабов от бьющихся сердец",[2]="и оставили горы изувеченных мертвецов."},
		["FourUniqueGlovesDex1_"] = {[1]="Дерись со свирепостью Первых."},
		["FourUniqueGlovesDex2"] = {[1]="После извержения небеса посерели, пепел",[2]="стал опускаться на землю, и настали холода..."},
		["FourUniqueGlovesDex4"] = {[1]="Дурная голова рукам покоя не даёт."},
		["FourUniqueGlovesDex5"] = {[1]="Как змея избегает раздумий,",[2]="они избегают страха,",[3]="кусая в порыве гнева",[4]="с неодолимой страстью."},
		["FourUniqueGlovesDex6"] = {[1]="Малигаро работал играючи: энергично",[2]="и с чудовищными последствиями."},
		["FourUniqueGlovesDex9"] = {[1]="Если страх тебя не прикончит, прикончу я."},
		["FourUniqueGlovesDexInt1"] = {[1]="Язвы, струпья и оспины – третья армия забирает своё."},
		["FourUniqueGlovesDexInt2"] = {[1]="«Швы? А разве смысл не в обратном?» ",[2]="- Джеффри, подмастерье дознавателя"},
		["FourUniqueGlovesDexInt5"] = {[1]="Ярились небеса, и тучи громоздились, рождение давая",[2]="четверым, что ненависти чадами зовутся."},
		["FourUniqueGlovesDexInt6"] = {[1]="Гром небесный",[2]="вселяет в сердца",[3]="не один только страх."},
		["FourUniqueGlovesInt1"] = {[1]="Расправы кровь и берег алый,",[2]="Вод обречённый вожделеть.",[3]="Богатство, жизнь, я всё отдал бы,",[4]="Лишь бы тебя запечатлеть."},
		["FourUniqueGlovesInt2"] = {[1]="Ты можешь быть фитилём или воском. Твой свет всё равно угаснет, а мой продолжит гореть."},
		["FourUniqueGlovesInt3"] = {[1]="Хотя Доэдре была лишена чувства стиля Малигаро,",[2]="она превосходила господина в чистой злобе."},
		["FourUniqueGlovesInt4"] = {[1]="Реальность – это головоломка. Изобретательность – сила."},
		["FourUniqueGlovesInt5"] = {[1]="Коварство Шибаквы прогневало небеса.",[2]="Один за другим, боги забирали его плоть,",[3]="пока не осталась лишь капля чистого света —",[4]="первый ваал."},
		["FourUniqueGlovesInt6"] = {[1]="Диамора поёт не от голода, а от тоски."},
		["FourUniqueGlovesInt7"] = {[1]="«Продолжай улыбаться. Глубже всего ранят не упрёки, а лживая похвала»."},
		["FourUniqueGlovesStr1"] = {[1]="«Считаешь, мы дикари? – раздумчиво произнёс",[2]="Красный волчара, выдирая зубы из черепа Вечного.",[3]="– Я покажу вашим путь зубов и когтей»."},
		["FourUniqueGlovesStr2"] = {[1]="Самые большие существа в Рэкласте",[2]="не из плоти и крови."},
		["FourUniqueGlovesStr3"] = {[1]="Зачем цепляться за рассудок? Он скуп на дары.",[2]="Отдайся мне, и дарам не будет конца."},
		["FourUniqueGlovesStr4"] = {[1]="Что хуже: укол прошлого, боль настоящего или страх будущего?"},
		["FourUniqueGlovesStr5"] = {[1]="«Сердце — лучший советчик. ",[2]="Оно подскажет, когда нанести удар».",[3]="- Атзири, царица ваал"},
		["FourUniqueGlovesStr7"] = {[1]="«Держи друзей на расстоянии меча,",[2]="а врагов – на расстоянии рукояти».",[3]="- Император Титус"},
		["FourUniqueGlovesStrDex1"] = {[1]="Шёпот старых богов гудит в железе. Они требуют героя."},
		["FourUniqueGlovesStrDex2"] = {[1]="С богатством приходят и обязательства."},
		["FourUniqueGlovesStrDex3"] = {[1]="Предвкушение – это дар."},
		["FourUniqueGlovesStrDex4"] = {[1]="В отличие от других богов, родившись из вулкана, Валако",[2]="верхом на клубах пепла пронёсся по грохочущему небу."},
		["FourUniqueGlovesStrDex5"] = {[1]="Крепчайшие души куются в тяготах и поражениях."},
		["FourUniqueGlovesStrInt1"] = {[1]="Как ни пытайся скрыть",[2]="кровь на своих руках, ",[3]="ты всё равно будешь знать правду."},
		["FourUniqueGlovesStrInt2"] = {[1]="Хочешь жить — умей вертеться."},
		["FourUniqueGlovesStrInt3"] = {[1]="Секрет унёс могилу его автор."},
		["FourUniqueGlovesStrInt4"] = {[1]="Лишь однажды Малигаро задумался, не зашёл ли он слишком далеко.",[2]="Его величайший успех привёл к пленению трёх целых легионов."},
		["FourUniqueHelmetDex1"] = {[1]="За безумием лежит вдохновение."},
		["FourUniqueHelmetDex10"] = {[1]="Конец всегда наступает раньше, чем мы думаем."},
		["FourUniqueHelmetDex11"] = {[1]="Природа почитает силу",[2]="и потому обагряет снег",[3]="кровью слабых."},
		["FourUniqueHelmetDex2"] = {[1]="Никакой песок не утекает сквозь пальцы так легко, как золотой."},
		["FourUniqueHelmetDex3"] = {[1]="Никто не горит в одиночку."},
		["FourUniqueHelmetDex5"] = {[1]="Древние почитатели Великого Волка были охвачены",[2]="ненасытной жаждой всего мистического."},
		["FourUniqueHelmetDex6"] = {[1]="«Будь бдителен, Незахул! Когда змея загнана в угол, разве она сдаётся?",[2]="Нет... Она ждёт. А затем жалит первую попавшуюся руку.",[3]="Опасность численного перевеса тебе только мнится!»",[4]="– Гадюка Напуаци отдаёт распоряжения царскому воеводе Незахулу"},
		["FourUniqueHelmetDex7"] = {[1]="Пираты Морской гнили живут в вечном огне славы,",[2]="испытывая удачу, пока не наступит конец."},
		["FourUniqueHelmetDex8"] = {[1]="Смерть Старконжи не сделала никого героем,",[2]="лишь превратила его долгую спячку в вечный сон."},
		["FourUniqueHelmetDex9"] = {[1]="Отрешись от жарких порывов,",[2]="отрекись от холодных расчётов,",[3]="и воздастся тебе за старания."},
		["FourUniqueHelmetDexInt1"] = {[1]="Корни зарываются глубже, обнажая дары леса..."},
		["FourUniqueHelmetDexInt2"] = {[1]="Ужас древних времён, чья личность",[2]="остаётся забытой... но не его сила."},
		["FourUniqueHelmetDexInt3"] = {[1]="Порознь мы не сравнимся с жестокостью толпы."},
		["FourUniqueHelmetDexInt4"] = {[1]="Оставаясь невидимым, Бесчестный Убийца нападал",[2]="только в глубине жесточайших песчаных бурь."},
		["FourUniqueHelmetDexInt5"] = {[1]="«Смотри и восхищайся своей царицей, но не касайся её».",[2]="- Атзири, царица ваал"},
		["FourUniqueHelmetDexInt6"] = {[1]="«Лёд обжигал наготу его ног,",[2]="молний страшилось сердце,",[3]="только любимого в пламени рот",[4]="требовал страшной мести».",[5]="- Виктарио из Сарна, поэма «Три дракона»"},
		["FourUniqueHelmetDexInt8"] = {[1]="Разверзлись небеса, сошлись черноты с синевой",[2]="Конец времён и сущего без всякого спасенья",[3]="Но в найденном осколке, в пустоте, в приюте",[4]="Они укрылись; и ждали там до нового начала",[5]="И волей тёмною, знанием полны противники Судьбы –",[6]="Им ведом разум твой, поскольку они помнят."},
		["FourUniqueHelmetInt1"] = {[1]="С осторожностью бери, примеряй неспешно.",[2]="Шипы снаружи и внутри, о том тебе известно."},
		["FourUniqueHelmetInt11"] = {[1]="Там, где начинаются границы тела,",[2]="Заканчиваются границы разума."},
		["FourUniqueHelmetInt2"] = {[1]="Дух жаждет податливую плоть."},
		["FourUniqueHelmetInt3"] = {[1]="Сказительницы не бьются как дехара.",[2]="Им подвластна сила совсем иного рода."},
		["FourUniqueHelmetInt4"] = {[1]="Держи сердце подобным льду,",[2]="дабы не тронули его страсти."},
		["FourUniqueHelmetInt5"] = {[1]="Плоть богов породила Шибакву.",[2]="Расправа над Шибаквой породила нас.",[3]="Мы должны возвратить богам то, что принадлежало им."},
		["FourUniqueHelmetInt6"] = {[1]="Они в экстазе выкрикивали её имя, расставаясь",[2]="с жизнью, а она смотрела в нетерпении."},
		["FourUniqueHelmetInt7"] = {[1]="Не представай пред пустотой,",[2]="что смотрит, не мигая, вдаль.",[3]="Иначе разум утлый твой",[4]="разрушен будет, так и знай."},
		["FourUniqueHelmetInt8"] = {[1]="«Чем острее боль, тем острее ум.",[2]="Любопытный парадокс».",[3]="- Шавронн из Умбрии"},
		["FourUniqueHelmetStr1a"] = {[1]="Младший брат ринулся в битву, отмахиваясь от ударов."},
		["FourUniqueHelmetStr1b"] = {[1]="Старший брат сохранял хладнокровие в бушующей гуще."},
		["FourUniqueHelmetStr2"] = {[1]="Годы служения, миг славы",[2]="и вечность смерти."},
		["FourUniqueHelmetStr3"] = {[1]="Больше всего мы боимся чудовищ,",[2]="которые таятся в кромешной тьме."},
		["FourUniqueHelmetStr4"] = {[1]="Мы можем сражаться и можем умереть, но в эти",[2]="минуты крови и сражений мы действительно живём."},
		["FourUniqueHelmetStr5"] = {[1]="Да не услышите вы звона его."},
		["FourUniqueHelmetStr6"] = {[1]="Совершать жертвоприношения могли только верховные жрецы,",[2]="но к ликованию присоединялись все присутствующие."},
		["FourUniqueHelmetStr8"] = {[1]="Око за око весь мир загубит."},
		["FourUniqueHelmetStrDex1"] = {[1]="В конце концов забываются даже герои."},
		["FourUniqueHelmetStrDex2"] = {[1]="Порой починка снаряжения",[2]="заходит слишком далеко."},
		["FourUniqueHelmetStrDex3"] = {[1]="Пусть не дрогнет рука всадника."},
		["FourUniqueHelmetStrDex4"] = {[1]="Он не говорил ни слова. Его соперники сами",[2]="воображали себе насмешки, самые жестокие."},
		["FourUniqueHelmetStrDex5"] = {[1]="Панибратство рождает пренебрежение."},
		["FourUniqueHelmetStrDex7"] = {[1]="– На чём ты стоишь?!",[2]="– На святой земле, в потоках кровавых слёз!"},
		["FourUniqueHelmetStrDex9_"] = {[1]="«Соберись. Заостри разум. Стоящие ниже тебя опираются на осязаемое.",[2]="Отбрось свои чувства, и сотри их из этой физической реальности»."},
		["FourUniqueHelmetStrInt1"] = {[1]="По руслу честолюбия течёт река, полная трупов."},
		["FourUniqueHelmetStrInt2"] = {[1]="Тяжела головушка."},
		["FourUniqueHelmetStrInt3"] = {[1]="Безмолвная воля",[2]="В тисках вечной ночи.",[3]="Питаются болью",[4]="Незрячие очи."},
		["FourUniqueHelmetStrInt4"] = {[1]="Семена величия сажают во тьме,",[2]="поливают страданиями и",[3]="вскармливают отчаянием.",[4]="Так вырастают стальные цветы победы."},
		["FourUniqueHelmetStrInt5"] = {[1]="Боль приносит ясность."},
		["FourUniqueHelmetStrInt6"] = {[1]="Смерть ползёт во мраке, ближе, чем мы думаем."},
		["FourUniqueHelmetStrInt9"] = {[1]="«Твои алчные руки только приближают",[2]="не-свет к поглощению твоего мира»."},
		["FourUniqueJewel1"] = {[1]="Источник жизненной силы, бурлящий изнутри."},
		["FourUniqueJewel10"] = {[1]="После пожаров, в глубине Всемирной зимы, вся жизнь в Вастири сплотилась. Будь то змей, гиена, человек или голем, ненавистные враги, скрепив вместе руки и когти, строили убежища и плечом к плечу сражались против созданий Бездны. Так возник Третий Договор."},
		["FourUniqueJewel11"] = {[1]="Они уверовали, что действовали из необходимости,",[2]="но эта безысходность сделала из них чудовищ."},
		["FourUniqueJewel12"] = {[1]="Бесчисленные души кричат в мучительной гармонии,",[2]="вечно утопая под массой новых умерших."},
		["FourUniqueJewel13"] = {[1]="«‎О боли не беспокойся, это просто... высвобождаем место. Отвлечённый факт,",[2]="человек может жить нормальной жизнью всего с одной почкой. Или одним лёгким.",[3]="Никогда не знаешь, чего тебе будет стоить технология ваал...»"},
		["FourUniqueJewel14_"] = {[1]="«‎Попробуй другую жизнь. Посмотри, годится ли она.",[2]="Ты найдёшь свою единственную жизнь совершенно недостаточной».",[3]="- Разноимённый и многоликий"},
		["FourUniqueJewel15"] = {[1]="Только безумец пропустит мимо ушей наставления бога."},
		["FourUniqueJewel2"] = {[1]="Неукротимая сила подчинения."},
		["FourUniqueJewel3"] = {[1]="Кожа похожа на сталь, закалённую ярким пламенем."},
		["FourUniqueJewel4"] = {[1]="Если собираешься вести себя так, как будто ты",[2]="лучше остальных, то лучше бы этому быть правдой."},
		["FourUniqueJewel5"] = {[1]="Они уверовали, что были мужественны и самоотверженны,",[2]="но эта храбрость накликала беду к ним на порог."},
		["FourUniqueJewel6"] = {[1]="Они выцарапывали себе путь из мучительных глубин небытия,",[2]="глубоко и сладко вдыхая изысканный свет значимости."},
		["FourUniqueJewel7"] = {[1]="Наш мир умирал, но мы выбрали жизнь.",[2]="Мы освободились от внутренних оков."},
		["FourUniqueJewel8"] = {[1]="Энтропию можно обратить."},
		["FourUniqueJewel9"] = {[1]="На пике своего величия ваал сверкали под солнцем.",[2]="Декада, век, эпоха процветания...",[3]="теперь всего лишь былое чудо."},
		["FourUniqueLifeFlask1"] = {[1]="«Пускай Тукохама дремлет, но он всё ещё даёт нам свою силу.",[2]="Маленькая игла, подношение и сосуд... пей до дна, мой сын,",[3]="и ты не просто переживёшь грядущую битву... ты преуспеешь»."},
		["FourUniqueLifeFlask2"] = {[1]="«Расчёты завершены, и Он собран воедино.",[2]="Наша безупречная тактика приведена в исполнение»."},
		["FourUniqueManaFlask1"] = {[1]="«Как я справляюсь с тем, что я видел на Рэкласте?",[2]="Хвала предкам! Мой кубок, он переполнен».",[3]="- Лавианга, бывший советник Каома"},
		["FourUniqueManaFlask2"] = {[1]="Утред отпил. Веризий обжёг ему вены.",[2]="Он взглянул в лицо смерти. Собрав все силы,",[3]="устремил глаза к звёздам. И узрел Истину."},
		["FourUniqueOneHandMace1"] = {[1]="Клеймо кузнеца было широко известно."},
		["FourUniqueOneHandMace13"] = {[1]="Посмотри в глаза буре и ты заслужишь её уважение."},
		["FourUniqueOneHandMace14"] = {[1]="«Вы, смертные, коварны. Вы подавляете своё зло,",[2]="или отрицаете его существование. Лжецы! Когда я",[3]="открываю ваши головы, это насилие льётся наружу».",[4]="– Ворон-Плут"},
		["FourUniqueOneHandMace15"] = {[1]="Обычный солдат из обычной семьи продолжал стучать молотом в ночи после",[2]="каждого изнуряющего марша, и глаза его горели звёздным светом и решимостью.",[3]="Мало кто подозревал, что однажды он станет величайшим среди них."},
		["FourUniqueOneHandMace2"] = {[1]="Кованый металл кузницы не забывает."},
		["FourUniqueOneHandMace3"] = {[1]="Милостивый убийца прошёл по Сарну,",[2]="забирая дыхание слабых и убогих."},
		["FourUniqueOneHandMace4"] = {[1]="Верность эзомитов доставалась не дальним правителям.",[2]="Заслуживали её сотоварищи в бою."},
		["FourUniqueOneHandMace5"] = {[1]="Твари Бездны появились благодаря сотворению,",[2]="а не рождению, и каждый миг на свету был пыткой."},
		["FourUniqueOneHandMace6"] = {[1]="Открывает окно в новый мир."},
		["FourUniqueOneHandMace7"] = {[1]="Они надеялись, что пленённое существо",[2]="будет стареть и чахнуть,",[3]="но время не могло даже коснуться твари."},
		["FourUniqueOneHandMace9"] = {[1]="«Капелька жидкого ободрения - обычный гарнир",[2]="к превосходному признанию».",[3]="- Изувер, Смотритель Аксиомы"},
		["FourUniquePinnacle1"] = {[1]="Люди Немигающего глаза не прятались в страхе.",[2]="Они восстали против конца."},
		["FourUniquePinnacle2"] = {[1]="Только один воин дожил до встречи с Судьёй."},
		["FourUniquePinnacle3"] = {[1]="Величайший воин своей эпохи бился с честью."},
		["FourUniquePinnacle4"] = {[1]="Его врага упорство крепло. Его же меркло."},
		["FourUniquePinnacle5"] = {[1]="Огонь уничтожает, но также и очищает.",[2]="Жизнь всегда появляется вновь."},
		["FourUniqueQuarterstaff1"] = {[1]="Кто тронет шип, тот боль и кровь найдёт."},
		["FourUniqueQuarterstaff14"] = {[1]="Дэнниг увидел Серену мысленным взором – публичный пример",[2]="экстравагантности. Пока она не принесла Кадигану сына и не пропала.",[3]="Упадок, скрывающий жестокость, как все калгууранские обычаи."},
		["FourUniqueQuarterstaff2"] = {[1]="Рождён повелевать волной",[2]="и в обезьяньих лапах быть.",[3]="Могуч, как бастион стальной.",[4]="Проворен, как игла швеи."},
		["FourUniqueQuarterstaff3"] = {[1]="В ночь, когда Дрейвен пошёл в атаку,",[2]="Эриан спал на своём посту."},
		["FourUniqueQuarterstaff5"] = {[1]="В наших легендах и наших сердцах реки всё ещё текут."},
		["FourUniqueQuarterstaff6"] = {[1]="Первый охотник на ведьм знал главный секрет:",[2]="не давай врагу время на раздумья."},
		["FourUniqueQuiver1"] = {[1]="Пар от дыхания оседает",[2]="льдом в горле, инеем на губах,",[3]="когда бывшие тёплыми падают",[4]="на замёрзшую пустошь."},
		["FourUniqueQuiver12"] = {[1]="«Зачем тратить славную стрелу всего на одного?»",[2]="- Кирави, лучник ваал"},
		["FourUniqueQuiver2_"] = {[1]="Стрел размытые черты,",[2]="шёпот их из темноты."},
		["FourUniqueQuiver3"] = {[1]="Жизнь и смерть проистекают из одной и той же капли."},
		["FourUniqueQuiver5"] = {[1]="«Мало у кого есть глаза на затылке».",[2]="- Кирави, лучник ваал"},
		["FourUniqueQuiver6"] = {[1]="«Варёные лягушки не для колдовства, дорогуша. Это",[2]="возмутительный слух. На самом деле они для ядов».",[3]="- Селассия с Чёрного болота"},
		["FourUniqueQuiver8"] = {[1]="«Целиком от каприза случая не избавиться, но правильными",[2]="манипуляциями любой исход можно обернуть в свою пользу...»",[3]="– Кадиро Перандус"},
		["FourUniqueRing1"] = {[1]="Раз всегда должно быть зло, пусть будет так.",[2]="Прими его. Стань его повелителем."},
		["FourUniqueRing10"] = {[1]="Владыки снегов",[2]="Заслужено место.",[3]="Славься в веках,",[4]="Мегинордова песня!"},
		["FourUniqueRing11"] = {[1]="Дориани наткнулся на царство безумия",[2]="и пробудил его государя."},
		["FourUniqueRing12"] = {[1]="Выковано последним оставшимся из братьев,",[2]="чтобы вернуть всё, что было когда-то отдано."},
		["FourUniqueRing13"] = {[1]="Македы хранят много секретов."},
		["FourUniqueRing14"] = {[1]="Спиралью он вьётся всё глубже",[2]="Меж мыслями он скользит",[3]="Лежит он под дном долины",[4]="Он в разуме нашем лежит"},
		["FourUniqueRing15"] = {[1]="Одно из колец трёх братьев,",[2]="по которым они узнавали друг друга",[3]="на любом расстоянии и в любом состоянии."},
		["FourUniqueRing16"] = {[1]="Мин забыл о Покое,",[2]="Хаос назвал невестой.",[3]="Палец супруги новой",[4]="он увенчал своим сердцем."},
		["FourUniqueRing17"] = {[1]="За вуалью смерти горит огонь,",[2]="из света которого рождается ночь."},
		["FourUniqueRing18"] = {[1]="Невинность вознёсся к богам не одухотворением,",[2]="но очернением и ненавистью к ближнему."},
		["FourUniqueRing19"] = {[1]="Воины Немигающего глаза шли вперёд",[2]="единым целым, плечом к плечу."},
		["FourUniqueRing20"] = {[1]="Тот больше ценит жизнь, кто видит ей конец."},
		["FourUniqueRing21"] = {[1]="Забрал я кольцо, они отняли палец.",[2]="Недолго глумились над сумрачным пением:",[3]="я души их отнял. Злодеи узнали,",[4]="что боком им вышло благословение."},
		["FourUniqueRing22"] = {[1]="Сила приходит к тем, кто ищет,",[2]="а смерть – к тем, кто находит."},
		["FourUniqueRing23"] = {[1]="Когда упал занесённый топор,",[2]="Сирил разделила его боль.",[3]="В его гаснущем сознании промелькнул",[4]="её надрывный, истошный крик."},
		["FourUniqueRing24"] = {[1]="Они обвиваются вокруг тебя, пока кровь твоя не станет такой же холодной, как их собственная."},
		["FourUniqueRing25"] = {[1]="Господь благословляет тех, кто сам себя благословил."},
		["FourUniqueRing26a"] = {[1]="«Берек укрылся от слепящего гнева Бури",[2]="в объятиях рассеянного Мороза.",[3]="Отброшенная льдом и ослепленная",[4]="метелями, Буря вотще бушевала,",[5]="пока Берек спал».",[6]="- Берек и Неукротимые"},
		["FourUniqueRing26b"] = {[1]="«В покрытых льдом владениях Мороза",[2]="смеялся Берек, колкости пуская.",[3]="Но Пламя злое охватило гору,",[4]="и зубоскал бежал по талым водам",[5]="под крики боли бедного Мороза».",[6]="- Берек и Неукротимые"},
		["FourUniqueRing26c"] = {[1]="«Когда Пламя лизало его пятки,",[2]="Берек бранил облака до тех пор,",[3]="пока злая Буря не извергла дожди.",[4]="Тогда Берек ухватился за твердь,",[5]="а Пламя изошло криком и паром.",[6]="И отступило».",[7]="- Берек и Неукротимые"},
		["FourUniqueRing27"] = {[1]="«Месяц за месяцем Берек дурачил",[2]="великую Троицу Неукротимых,",[3]="пока злость на Брата не затмила",[4]="ненависть к Пришлому.",[5]="Тогда Берек ушел на охоту,",[6]="одинокий и свободный».",[7]="- Берек и Неукротимые"},
		["FourUniqueRing28"] = {[1]="Соглашение с Просперо всегда обходится недёшево."},
		["FourUniqueRing29"] = {[1]="Без риска не бывает богатства."},
		["FourUniqueRing2a"] = {[1]="Те из Братства, кто использует яд ледяных змей Тератны,",[2]="должны быть очень осторожны с летучим веществом."},
		["FourUniqueRing2b"] = {[1]="Способ пережить укус ледяной змеи есть,",[2]="но не многим достанет решимости попробовать."},
		["FourUniqueRing3"] = {[1]="Агония дарует ясность чистому разуму."},
		["FourUniqueRing30"] = {[1]="В сиянии славы немыслимое чудовище",[2]="столкнулось с божественным провидением.",[3]="Так Вентор встретил свою последнюю добычу."},
		["FourUniqueRing32"] = {[1]="Власть — вопрос точки зрения."},
		["FourUniqueRing33"] = {[1]="Испей сполна из Колодца.",[2]="Пусть вьётся внутри Бездна.‎"},
		["FourUniqueRing34"] = {[1]="Племя гуляло напропалую, не ведая о том, что каждый",[2]="съеденный ими фрукт всё теснее связывает их с туманом.",[3]="А позже легчайшее касание могло разбить их реальность."},
		["FourUniqueRing4"] = {[1]="Когда их глаза привыкли к темноте, они увидели странный",[2]="синий свет. Наверху ползли мириады светящихся червячков,",[3]="счастливые в своём неведении об их бегстве от сирен."},
		["FourUniqueRing5"] = {[1]="На месте рта её клубилось чёрное ничто."},
		["FourUniqueRing6"] = {[1]="Близится заря новой эпохи."},
		["FourUniqueRing7"] = {[1]="Бойся огня, что распространяется как чума."},
		["FourUniqueRing8"] = {[1]="«‎Безмолвное братство не ставит перед собой задачу истязать наши цели.",[2]="Нестерпимая боль – это лишь побочный результат определённых... вынужденных мер»."},
		["FourUniqueRitual1"] = {[1]="Небытие не любит ослаблять свою хватку.",[2]="Каждый миг – борьба за существование."},
		["FourUniqueRitual2"] = {[1]="Они кишат, пищат и ползут",[2]="в его тени."},
		["FourUniqueRitual3"] = {[1]="Маджи не ожидали, что столько узнают",[2]="благодаря экспериментам с геомантией."},
		["FourUniqueRitual4"] = {[1]="В бесконечной войне против тьмы",[2]="нельзя терять бдительность."},
		["FourUniqueSanctum1"] = {[1]="В последнюю очередь сказительницы",[2]="овладели самим Временем."},
		["FourUniqueSanctum2"] = {[1]="Злой ветер несёт смерть."},
		["FourUniqueSanctum3"] = {[1]="«‎Мы пережили бесконечную зиму.",[2]="Мы стерпели долгое лето.",[3]="Однажды весной вернутся дожди»."},
		["FourUniqueSanctum4a"] = {[1]="Ваал защищали тех, кто влился в их культуру. Многие",[2]="соседи объединились. Сехема Сафрин поклялась, что",[3]="собственный характер маракетов останется твёрд."},
		["FourUniqueSanctum4b"] = {[1]="Во время Всемирной зимы её ахара начала проводить",[2]="джингах через суровую Вастири. Сехема Эштера",[3]="посеяла семена маракетской дипломатии."},
		["FourUniqueSanctum4c"] = {[1]="Относительный мир под оперившейся империей позволил",[2]="первой Сехеме, в её многовеликом возрасте и мудрости,",[3]="отказаться от власти. Так родилась роль Зайтемы."},
		["FourUniqueSceptre1"] = {[1]="Редок тот некромант, что командует",[2]="своей армией нежити из первых рядов."},
		["FourUniqueSceptre14"] = {[1]="Воет тьма в костях старинных, тоскливый плач на",[2]="гулком ветру. Луна слушает. Стая находит друг друга."},
		["FourUniqueSceptre4"] = {[1]="Сказительницам не дозволено биться",[2]="самим, ибо задача их куда важней."},
		["FourUniqueSceptre6"] = {[1]="«Когда Третий Договор был высечен в камне, Спящий дал союзу людей и чудищ знание.",[2]="Взамен они отдали ему каплю крови; по одной от каждой расы, населяющей Рэкласт.",[3]="В последующие столетия его Воля начала незаметно меняться».",[4]="– Книга Милостивого Спящего, Хроники, 220:5"},
		["FourUniqueSceptre6a"] = {[1]="«Сила Красного Костра! Пылающее сердце Улья!",[2]="Я оставляю твоё горящее послание здесь на веки вечные»,",[3]="– провозгласил Спящий, отбросив от себя тлеющие тёмные угли."},
		["FourUniqueSceptre6b"] = {[1]="«Пронзительным взглядом ты узрела через Застой.",[2]="Единой волной ты великолепно покрыла всё белым.",[3]="Но... Я не могу больше носить тебя»,",[4]="– прошептал Спящий с облачком пара у рта, чувствуя стылость в руке."},
		["FourUniqueSceptre6c"] = {[1]="«Погрузившись в размышления, ты колебал сам воздух перед собой.",[2]="Окутанный светом, ты вырастил их всех.",[3]="И всё же... твоя природа взяла своё»,",[4]="– пробормотал Спящий с болью на сердце, когда вперёд вырвались остатки ветвящихся побегов."},
		["FourUniqueSceptre6d"] = {[1]="«Иногда мы не справляемся. Иногда мы преуспеваем. Кто отделяет одно от другого?",[2]="Теперь я знаю, что мы никогда не станем Едины, если рождены от разных желаний.",[3]="И всё же я надеюсь на новую правду. И я позабочусь, чтобы она... воплотилась».",[4]="– Милостивый Спящий"},
		["FourUniqueShieldDex1"] = {[1]="«Вором в ночи Дрейвен в деревню пробрался,",[2]="спящие семьи забрал и трофеями выставил.",[3]="Умно, думал он, но платить его детям пришлось.",[4]="Нет уж, злодей, страдать ты не будешь один»."},
		["FourUniqueShieldDex11_"] = {[1]="«‎Нет такого места, где моя месть тебя не найдёт»."},
		["FourUniqueShieldDex12"] = {[1]="«Лундара сдерживала орды, а Солераи поднялась и разверзла небо.",[2]="Так одним взмахом она положила конец Всемирной зиме».",[3]="- Уранга, сказительница ахара Вахида"},
		["FourUniqueShieldDex2"] = {[1]="Свет и тень испокон веков преследуют друг друга,",[2]="но свету неведома тень, а тени неведом свет..."},
		["FourUniqueShieldDex3"] = {[1]="Сопротивляйся достаточно долго, и твой",[2]="угнетатель лишится воли. Тогда ты победил."},
		["FourUniqueShieldDex4"] = {[1]="Окошко в мир багровый, где криком",[2]="заходятся тысячи голосов..."},
		["FourUniqueShieldDex5"] = {[1]="Жалок, простужен и одинок... зато жив."},
		["FourUniqueShieldDex6"] = {[1]="Ещё мальцом на арене Дарессо научился притворяться",[2]="ослабшим, чтобы открыть путь для смертельного удара."},
		["FourUniqueShieldStr1"] = {[1]="Претор Дрейвен знал, что единственным шансом",[2]="покорить эзомитов будет застать их врасплох."},
		["FourUniqueShieldStr13"] = {[1]="Огонь танцует на поле сомнений",[2]="и лижет кожу, облитую страхом.",[3]="Где нет страха и сомнений,",[4]="там нет и огня."},
		["FourUniqueShieldStr14"] = {[1]="«На равнинах вечного хлада...",[2]="господствуют Те-Что-Не-Устают.",[3]="Те-Что-Не-Сдаются... ужасают.",[4]="А Те-Кто-Лежит-Внизу...",[5]="ждут наступления ночи».",[6]="- Тул, Та-Что-Заставляет молчать"},
		["FourUniqueShieldStr2"] = {[1]="Все Графы Огама были людьми",[2]="хваткими и сильными."},
		["FourUniqueShieldStr3"] = {[1]="Добро пожаловать в Рэкласт."},
		["FourUniqueShieldStr4"] = {[1]="«‎Спустя огонь, кровь и ужас",[2]="Спаситель воздвигнет утопию»."},
		["FourUniqueShieldStr5"] = {[1]="Некоторые истории не рассказывают."},
		["FourUniqueShieldStr6"] = {[1]="Настоящий хищник не преследует добычу, а ждёт её."},
		["FourUniqueShieldStr7"] = {[1]="Пролитая кровь — разделённая кровь."},
		["FourUniqueShieldStr8"] = {[1]="Наши сердца вопиют,",[2]="но тела не пропустят крик.",[3]="Потому мы отказываемся от тел."},
		["FourUniqueShieldStrDex1"] = {[1]="Бесконечная бойня войны",[2]="безжалостно истирает",[3]="и тело, и разум."},
		["FourUniqueShieldStrDex12"] = {[1]="Сквозь эпохи Дэнниг ощутил испытующий взгляд",[2]="Рунного отца. Нет чести в лёгком успехе.",[3]="Подлинное величие вырывают из лап поражения."},
		["FourUniqueShieldStrDex2"] = {[1]="Подавай пример, и ты никогда не будешь один."},
		["FourUniqueShieldStrDex4"] = {[1]="Оседлай западный ветер и взмой в небеса."},
		["FourUniqueShieldStrInt1"] = {[1]="Да не дрогнет твоя решимость."},
		["FourUniqueShieldStrInt2"] = {[1]="Друиды поклялись оберегать Грельвуд ценой собственной жизни."},
		["FourUniqueShieldStrInt3"] = {[1]="Проворный разум находит ответы до появления вопросов."},
		["FourUniqueShieldStrInt4"] = {[1]="Народ Ардура первым ответил",[2]="на зов Алой Сехемы."},
		["FourUniqueShieldStrInt5"] = {[1]="При плате кровью слабый подумает дважды."},
		["FourUniqueShieldStrInt6"] = {[1]="Владеющий мной ограждён пламенем,",[2]="ибо я — Феникс в сиянии славы вечном."},
		["FourUniqueSpear1"] = {[1]="Порча Камня мора по сей день не исчезла..."},
		["FourUniqueSpear13"] = {[1]="Копьё выковали специально для убийства Волла,",[2]="но Малигаро так и не выпал шанс его использовать.."},
		["FourUniqueSpear14"] = {[1]="«‎Мой народ? Я делаю это не ради них.",[2]="Они принадлежат мне. Они хотят этого для меня.",[3]="Их жертва – это дар, который они приносят из любви",[4]="и обожания... я заслуживаю его. Я их царица»."},
		["FourUniqueSpear15"] = {[1]="Пускай Бессветные утонут в насилии поклонения Ему."},
		["FourUniqueSpear2"] = {[1]="Вечная Империя была могущественной и грозной, но",[2]="мятежники всех стран восстали сообща единым фронтом."},
		["FourUniqueSpear3"] = {[1]="Священную охоту венчает милосердие."},
		["FourUniqueSpear4"] = {[1]="Головы летят на песок, как звёзды с небес."},
		["FourUniqueSpear5"] = {[1]="«Вы убили их Золотую Сехему. Теперь маракеты",[2]="не смогут думать ни о чём кроме мести».",[3]="- Димос, советник Легата Титуция"},
		["FourUniqueSpear6"] = {[1]="«В руках Орбалы он пустил кровь богу».",[2]="- Уранга, сказительница ахара Вахида"},
		["FourUniqueSpear7"] = {[1]="Рождённое в звезде, что создал человек,",[2]="последний просчёт с рукой спаял навек."},
		["FourUniqueSpirit1"] = {[1]="Чтобы стать воином и охотником, каждый молодой",[2]="азмири должен доказать свою силу Духу."},
		["FourUniqueStaff1"] = {[1]="Традиция сретения родилась во времена темноты и страха."},
		["FourUniqueStaff13"] = {[1]="В жутких ямах на дне мира",[2]="Кулемак растит бессчётные новые тела,",[3]="каждое новое сильнее прежнего.",[4]="Не все его исчадия выживают."},
		["FourUniqueStaff14"] = {[1]="«Какая тварь тебя породила, нам остаётся лишь гадать.",[2]="Ты, кусок живого льда, гниющих жабр и нечистого кошмара!",[3]="Морская гниль бросает тебя назад в пучину».",[4]="- Вейлам Рот"},
		["FourUniqueStaff17"] = {[1]="Склонись перед ней... или испытай самую мучительную смерть, какую только можно представить."},
		["FourUniqueStaff18"] = {[1]="«Куда бы ни шёл мальчик, там собирались вороны,",[2]="пируя на несчастии. Его жестокое влияние",[3]="росло так же быстро, как несомая ими расправа»."},
		["FourUniqueStaff2"] = {[1]="Оставленный крылатым зверем ночи,",[2]="рог чешуёй и морозью одет.",[3]="И всякий, кто глядит на хладный свет,",[4]="дрожит от боли и отводит очи."},
		["FourUniqueStaff3"] = {[1]="Древний посох азмири, поросший корнями..."},
		["FourUniqueStaff5"] = {[1]="Сжигай дотла всех, кто не с нами.",[2]="Правь миром, что объяло пламя."},
		["FourUniqueStaff6"] = {[1]="И сломанное может ломать."},
		["FourUniqueTalisman1"] = {[1]="Немногие восприимчивые среди первых поселенцев Эзомира",[2]="последовали за огоньками на каноэ. На туманном заросшем",[3]="лесами острове их дожидался и приветствовал Сирэл Тарт."},
		["FourUniqueTalisman10"] = {[1]="«Традиционно хатанго не носят топора,",[2]="это правда. Но, как показала нам Нарумоа,",[3]="есть много способов сокрушить врага...»"},
		["FourUniqueTalisman14"] = {[1]="Граткул была Матерью отчаяния,",[2]="но однажды вернётся и Отец,",[3]="и увидит судьбу своих детей."},
		["FourUniqueTalisman2"] = {[1]="Если ты видишь цветущее дерево в северных лесах, помни:",[2]="«Если цвет красный, напоено древо кровью несчастных.",[3]="А если цвет белый, готовься к бою смело»."},
		["FourUniqueTalisman4"] = {[1]="В час великой нужды, в окружении созданий Бездны,",[2]="Своенравный друид пришёл на помощь клану Солнца.",[3]="Это долг, который они до сих пор не забыли."},
		["FourUniqueTalisman8"] = {[1]="Когда-то давно азакские ведьмы научились",[2]="вмешиваться в течение буйной жизненной силы,",[3]="чтобы «‎сотрудничать» с врагами... насильственно."},
		["FourUniqueTwoHandMace1"] = {[1]="Есть крайне простая и аппетитная причина,",[2]="почему эзомиты решили прекратить бегство",[3]="и осесть в Фаариле."},
		["FourUniqueTwoHandMace10"] = {[1]="«‎Пьяный Эрки хвалился перед Тукохамой; Бог войны",[2]="вызвал его на поединок силы. Горе было божеству –",[3]="надо было устраивать испытание уменья!»"},
		["FourUniqueTwoHandMace13"] = {[1]="Тайный Орден выстоял, проповедуя на",[2]="публику то, что было угодно жрецам.",[3]="Однажды правосудие их настигло..."},
		["FourUniqueTwoHandMace14"] = {[1]="Бесконечные мутации, накопленные за бесчисленные эпохи и воплотившиеся в один-единственный миг."},
		["FourUniqueTwoHandMace2"] = {[1]="«Хруст костей и бульканье крови.",[2]="Это ли не сладчайшая музыка?»",[3]="– Гримнор из народа эзомитов"},
		["FourUniqueTwoHandMace3"] = {[1]="Хирурги учатся на ошибках."},
		["FourUniqueTwoHandMace4"] = {[1]="Разум бессмертен — в отличие от его вместилища."},
		["FourUniqueTwoHandMace5"] = {[1]="Тишина и таинственность сами по себе сила."},
		["FourUniqueTwoHandMace6"] = {[1]="Да не обманет тебя людское вероломство."},
		["FourUniqueTwoHandMace7"] = {[1]="Верные продолжат служить даже после смерти."},
		["FourUniqueTwoHandMace8"] = {[1]="«Истинное процветание рождается из трагедий.",[2]="Такова природа прогресса».",[3]="– Дориани из рода ваал"},
		["FourUniqueTwoHandMace9"] = {[1]="Море без устали бьётся о скалу.",[2]="Через день или десять тысяч лет",[3]="камень всё равно обратится в пыль,",[4]="приумножив вотчину Морского Царя."},
		["FourUniqueUltimatum1"] = {[1]="Человек сохраняет рассудок и стремится к цивилизации ",[2]="только под благословенной завесой невежества."},
		["FourUniqueUltimatum2"] = {[1]="Самые кошмарные идеи часто берут начало из простого нововведения."},
		["FourUniqueUltimatum3"] = {[1]="Изгнанный архитектор стремился использовать все самые тёмные секреты ваал."},
		["FourUniqueUltimatum4"] = {[1]="Первые каруи, рождённые на окраинах империи ваал, страдали от кровавой лихорадки, вызванной порчей."},
		["FourUniqueWand1"] = {[1]="Мановением руки их судьбы были написаны,",[2]="а страницы разорваны на миллион клочков."},
		["FourUniqueWand15"] = {[1]="И в тот момент кости Вириди стали",[2]="ветками, оплетающими Темноту.",[3]="Она обвилась вокруг ничего,",[4]="заключив его в своём всём."},
		["FourUniqueWand16"] = {[1]="Выкована из древнего металла,",[2]="принесённого самими звёздами.",[3]="Это способ воззвать к ним,",[4]="для того, кто способен им овладеть."},
		["FourUniqueWand2"] = {[1]="Так или иначе, он найдёт свою цель."},
		["FourUniqueWand3"] = {[1]="И в Рэкласте осталась жизнь,",[2]="от крохотных семян",[3]="до стройных кипарисов."},
		["FourUniqueWand4"] = {[1]="Адония вскочила с пылающими глазами, испуская жуткую ауру,",[2]="и отбила кусок резьбы со стены тронного зала.",[3]="«Думаешь, без жезла я бессильна? Посмей только ещё раз меня оскорбить!»"},
		["FourUniqueWand5"] = {[1]="Его одного привечали в священных землях Титанов."},
		["FourUniqueWand7"] = {[1]="Заблудившись на Чёрном болоте, Эриан надеялся, что его спасёт заря.",[2]="Он знать не знал, насколько далёк был свет на самом деле."},
		["VaalLimbReplacements"] = {[1]="«Узрите! Чудо инновации! Не обращайте внимания на потерю плоти...»",[2]="- Гвателитзи, Архитектор плоти"},
	},
	leagues = {["standard"]="Стандарт",["settlers"]="Поселенцы",["dawn of the hunt"]="Начало охоты",["rise of the abyssal"]="Пробуждение Бездны",["fate of the vaal"]="Фатум ваал",["runes of aldur"]="Руны Альдура",["forbidden rites"]="Запретные ритуалы"},
